const highMath = [];
for (let i = 0; i < 27; i++) {
  const a = (i % 5) + 1;
  const b = (i % 7) - 3;
  const x = (i % 6) - 2;
  const value = a * x + b;
  const functionDistractors = [];
  for (const candidate of [value + a, value - b, a * (x + 1) + b, -value]) {
    if (candidate !== value && !functionDistractors.includes(candidate))
      functionDistractors.push(candidate);
  }
  let functionFiller = value + 1;
  while (functionDistractors.length < 3) {
    if (
      functionFiller !== value &&
      !functionDistractors.includes(functionFiller)
    )
      functionDistractors.push(functionFiller);
    functionFiller += 1;
  }
  highMath.push(
    question(
      `high1-math-q-${String(i + 1).padStart(2, "0")}`,
      `함수 f(x)=${a}x${b >= 0 ? `+${b}` : b}가 있을 때 f(${x})의 값은?`,
      `${value}`,
      functionDistractors.map(asText),
      `정의식에 x=${x}를 대입하면 ${a}×${x}${b >= 0 ? `+${b}` : b}=${value}이다.`,
      (i % 3) + 1,
      i % 4,
    ),
  );
}
for (let i = 0; i < 27; i++) {
  const start = i + 1;
  const aCount = 4 + (i % 3);
  const bCount = 3 + (i % 4);
  const intersection = (i % 3) + 1;
  const bStart = start + aCount - intersection;
  const bEnd = bStart + bCount - 1;
  const setA = Array.from({ length: aCount }, (_, index) => start + index);
  const setB = Array.from({ length: bCount }, (_, index) => bStart + index);
  const union = aCount + bCount - intersection;
  const query = i % 2 === 0 ? "합집합의 원소 수" : "교집합의 원소 수";
  const correct = i % 2 === 0 ? `${union}` : `${intersection}`;
  highMath.push(
    question(
      `high1-math-q-${String(i + 28).padStart(2, "0")}`,
      `집합 A={${setA.join(",")}}와 B={${setB.join(",")}}에서 ${query}는?`,
      correct,
      [`${union + 1}`, `${intersection - 1}`, `${aCount + bCount + 1}`],
      i % 2 === 0
        ? `두 집합의 가장 작은 원소부터 가장 큰 원소까지 중복을 한 번만 세면 ${union}개이다.`
        : `두 집합에 공통으로 들어가는 원소를 직접 비교하면 ${intersection}개이다.`,
      (i % 3) + 1,
      i % 4,
    ),
  );
}
for (let i = 0; i < 26; i++) {
  const x1 = i - 5;
  const y1 = (i % 9) - 4;
  const dx = (i % 5) + 1;
  const dy = (i % 7) - 3;
  const x2 = x1 + dx;
  const y2 = y1 + dy;
  if (i % 3 === 0) {
    const correct = `${dy}/${dx}`;
    highMath.push(
      question(
        `high1-math-q-${String(i + 55).padStart(2, "0")}`,
        `두 점 (${x1},${y1}), (${x2},${y2})를 지나는 직선의 기울기는?`,
        correct,
        [`${dy + 1}/${dx}`, `${dy - 1}/${dx}`, `${dy + 2}/${dx}`],
        `기울기는 y좌표의 변화량 ${dy}를 x좌표의 변화량 ${dx}로 나눈 ${correct}이다.`,
        (i % 3) + 1,
        i % 4,
      ),
    );
  } else {
    const mx = (x1 + x2) / 2;
    const my = (y1 + y2) / 2;
    const correct = `(${mx}, ${my})`;
    highMath.push(
      question(
        `high1-math-q-${String(i + 55).padStart(2, "0")}`,
        `선분의 양 끝점이 (${x1},${y1}), (${x2},${y2})일 때 중점은?`,
        correct,
        [`(${mx + 1}, ${my})`, `(${x1}, ${y2})`, `(${mx}, ${my + 1})`],
        `중점 좌표는 각 좌표의 평균이므로 (${x1}+${x2})/2=${mx}, (${y1}+${y2})/2=${my}이다.`,
        (i % 3) + 1,
        i % 4,
      ),
    );
  }
}

