const examMath = [];
for (let i = 0; i < 27; i++) {
  const a = (i % 4) + 1;
  const b = (i % 9) - 4;
  const c = (i % 5) - 2;
  const x = i - 4;
  const value = a * x * x + b * x + c;
  examMath.push(
    question(
      `exam-math-q-${String(i + 1).padStart(2, "0")}`,
      `다항함수 f(x)=${a}x²${b >= 0 ? `+${b}` : b}x${c >= 0 ? `+${c}` : c}에 대하여 f(${x})의 값과 그래프의 대칭에 관한 설명으로 옳은 것은?`,
      `f(${x})=${value}이고 대칭축은 x=${-b / (2 * a)}이다`,
      [
        `f(${x})=${value + a}이고 대칭축은 x=${b / (2 * a)}이다`,
        `f(${x})=${value - (a + 1)}이고 대칭축은 x=${-b / a}이다`,
        `f(${x})=${value + a + Math.abs(c) + 1}이고 대칭축은 x=0이다`,
      ],
      `대입 계산으로 f(${x})=${value}이며 이차함수의 대칭축은 -b/(2a)=${-b / (2 * a)}이다.`,
      (i % 3) + 1,
      i % 4,
    ),
  );
}
for (let i = 0; i < 27; i++) {
  const first = (i % 8) - 3 || 1;
  const diff = (i % 6) + 1;
  const n = (i % 5) + 4;
  const arithmetic = first + (n - 1) * diff;
  const sum = ((first + arithmetic) * n) / 2;
  const geometric = i % 3 === 0;
  if (!geometric) {
    examMath.push(
      question(
        `exam-math-q-${String(i + 28).padStart(2, "0")}`,
        `첫째항이 ${first}, 공차가 ${diff}인 등차수열의 ${n}번째 항과 첫 ${n}항의 합은?`,
        `제${n}항 ${arithmetic}, 합 ${sum}`,
        [
          `제${n}항 ${arithmetic + diff}, 합 ${sum + first}`,
          `제${n}항 ${first + n * diff}, 합 ${sum * 2}`,
          `제${n}항 ${arithmetic}, 합 ${arithmetic * n}`,
        ],
        `aₙ=a₁+(n-1)d=${arithmetic}, Sₙ=n(a₁+aₙ)/2=${sum}이다.`,
        (i % 3) + 1,
        i % 4,
      ),
    );
  } else {
    const ratio = 2 + (Math.floor(i / 3) % 3);
    const term = first * ratio ** (n - 1);
    const gsum = (first * (ratio ** n - 1)) / (ratio - 1);
    examMath.push(
      question(
        `exam-math-q-${String(i + 28).padStart(2, "0")}`,
        `첫째항이 ${first}, 공비가 ${ratio}인 등비수열에서 ${n}번째 항과 첫 ${n}항의 합은?`,
        `제${n}항 ${term}, 합 ${gsum}`,
        [
          `제${n}항 ${term / ratio}, 합 ${gsum - first}`,
          `제${n}항 ${first + ratio * n}, 합 ${term * n}`,
          `제${n}항 ${term + first}, 합 ${gsum + term}`,
        ],
        `aₙ=a₁rⁿ⁻¹=${term}, Sₙ=a₁(rⁿ-1)/(r-1)=${gsum}이다.`,
        (i % 3) + 1,
        i % 4,
      ),
    );
  }
}
for (let i = 0; i < 26; i++) {
  const a = (i % 5) + 1;
  const b = (i % 7) - 3;
  const x = (i % 6) - 2;
  const derivative = 2 * a * x + b;
  if (i % 2 === 0) {
    const value = a * x * x + b * x + (i % 4);
    examMath.push(
      question(
        `exam-math-q-${String(i + 55).padStart(2, "0")}`,
        `f(x)=${a}x²${b >= 0 ? `+${b}` : b}x+${i % 4}의 x=${x}에서 접선 기울기는?`,
        `${derivative}`,
        [`${derivative + 1}`, `${derivative - 1}`, `${-derivative}`],
        `f'(x)=${2 * a}x${b >= 0 ? `+${b}` : b}이므로 x=${x}에서 ${derivative}이다. 함수값 ${value}는 기울기 계산에 영향을 주지 않는다.`,
        (i % 3) + 1,
        i % 4,
      ),
    );
  } else {
    const lower = i % 4;
    const upper = lower + 2 + (i % 4);
    const integral =
      (a * (upper ** 3 - lower ** 3)) / 3 + (b * (upper ** 2 - lower ** 2)) / 2;
    examMath.push(
      question(
        `exam-math-q-${String(i + 55).padStart(2, "0")}`,
        `F'(x)=${a}x²${b >= 0 ? `+${b}` : b}x이고 F(${lower})=0일 때 F(${upper})는?`,
        `${integral}`,
        [`${integral + a}`, `${a * (upper - lower) ** 2}`, `${integral / 2}`],
        `미적분의 기본정리에 따라 F(${upper})-F(${lower})=∫${lower}^${upper}F'(x)dx=${integral}이고 F(${lower})=0이다.`,
        (i % 3) + 1,
        i % 4,
      ),
    );
  }
}

