const middleScience = [];
const motionObjects = [
  "실험용 자전거",
  "스케이트보드",
  "운반 카트",
  "공",
  "소형 썰매",
  "드론 모형",
  "엘리베이터 모형",
  "열차 모형",
  "달리기 선수의 장비",
];
for (let i = 0; i < 27; i++) {
  const mass = 1 + (i % 8);
  const velocity = 2 + (i % 7);
  const height = 2 + (i % 6);
  const object = motionObjects[i % motionObjects.length];
  const kinetic = (mass * velocity * velocity) / 2;
  const potential = mass * 10 * height;
  const askKinetic = i % 2 === 0;
  const askedEnergy = askKinetic ? kinetic : potential;
  const momentumDistractor = mass * velocity + 1;
  let additiveDistractor = mass + velocity + height;
  while ([askedEnergy, momentumDistractor].includes(additiveDistractor))
    additiveDistractor += 1;
  middleScience.push(
    question(
      `mid-science-q-${String(i + 1).padStart(2, "0")}`,
      `${object}의 질량이 ${mass}kg, 속력이 ${velocity}m/s, 기준면에서 높이가 ${height}m이다. 공기 저항을 무시할 때 ${askKinetic ? "운동 에너지" : "중력 위치 에너지"}는? (g=10m/s²)`,
      `${askedEnergy}J`,
      [
        askKinetic ? `${potential}J` : `${kinetic}J`,
        `${momentumDistractor}J`,
        `${additiveDistractor}J`,
      ],
      askKinetic
        ? `운동 에너지는 ½mv²이므로 ½×${mass}×${velocity}²=${kinetic}J이다.`
        : `중력 위치 에너지는 mgh이므로 ${mass}×10×${height}=${potential}J이다.`,
      (i % 3) + 1,
      i % 4,
    ),
  );
}
const heredityCases = [
  ["완두의 씨 색", "Y", "y", "노랑", "초록"],
  ["꽃 색", "R", "r", "빨강", "흰색"],
  ["털 길이", "L", "l", "짧음", "김"],
  ["눈 색", "B", "b", "갈색", "푸름"],
  ["종자 표면", "S", "s", "매끈", "주름"],
  ["날개 무늬", "D", "d", "무늬", "민무늬"],
  ["열매 모양", "P", "p", "둥금", "길쭉"],
  ["잎 가장자리", "E", "e", "톱니", "밋밋"],
  ["몸통 색", "C", "c", "진함", "옅음"],
  ["꽃받침", "K", "k", "큼", "작음"],
  ["뿌리 굵기", "T", "t", "굵음", "가늘음"],
  ["열매 색", "G", "g", "녹색", "노랑"],
  ["줄기 높이", "H", "h", "키 큼", "키 작음"],
  ["잎 색", "A", "a", "짙음", "연함"],
  ["씨 껍질", "M", "m", "단단", "부드러움"],
  ["꽃 향", "F", "f", "강함", "약함"],
  ["열매 껍질", "U", "u", "두꺼움", "얇음"],
  ["뿌리 색", "V", "v", "흰색", "갈색"],
  ["줄기 속", "N", "n", "차 있음", "비어 있음"],
  ["잎 배열", "Q", "q", "마주남", "어긋남"],
  ["씨 크기", "Z", "z", "큰 씨", "작은 씨"],
  ["꽃잎 수", "J", "j", "많음", "적음"],
  ["덩굴 방향", "W", "w", "오름", "내림"],
  ["가시 유무", "X", "x", "있음", "없음"],
  ["수분 시기", "O", "o", "빠름", "늦음"],
  ["열매 단맛", "I", "i", "달콤", "담백"],
  ["잎 두께", "S", "s", "두꺼움", "얇음"],
];
for (let i = 0; i < heredityCases.length; i++) {
  const [trait, dominant, recessive, dominantName, recessiveName] =
    heredityCases[i];
  const cross =
    i % 3 === 0
      ? `${dominant}${recessive} × ${dominant}${recessive}`
      : `${dominant}${dominant} × ${dominant}${recessive}`;
  const heteroChance = "50%";
  const dominantChance = i % 3 === 0 ? "75%" : "100%";
  const prompt = `${trait}에서 ${dominant}가 우성, ${recessive}가 열성이다. 부모의 유전자형이 ${cross}일 때 자손의 표현형과 유전자형에 대한 설명으로 옳은 것은?`;
  middleScience.push(
    question(
      `mid-science-q-${String(i + 28).padStart(2, "0")}`,
      prompt,
      `${dominantLabel(dominantName, recessiveName)} 우성 표현형이 나타날 확률 ${dominantChance}, 이형접합 확률 ${heteroChance}`,
      [
        `열성 표현형이 항상 ${dominantChance}이다`,
        `모든 자손이 ${dominant}${dominant}이다`,
        `우성 대립유전자는 세대를 건너뛸 수 없다`,
      ],
      `우성 대립유전자가 하나라도 있으면 ${dominantName}이 나타난다. 이 교배에서는 우성 표현형이 ${dominantChance}, ${dominant}${recessive} 이형접합이 ${heteroChance}이다.`,
      (i % 3) + 1,
      i % 4,
    ),
  );
}
function dominantLabel(dominantName, recessiveName) {
  return `${dominantName}/${recessiveName} 형질에서`;
}
