const highScience = [];
for (let i = 0; i < 27; i++) {
  const mass = 2 + (i % 7);
  const acceleration = 1 + (i % 5);
  const force = mass * acceleration;
  const additiveForce =
    mass + acceleration === force ? force + 1 : mass + acceleration;
  const setup = [
    "엘리베이터",
    "완충 장치",
    "수레",
    "풍력 터빈",
    "자기 부상 열차",
    "스프링 발사기",
    "경사면",
    "드론",
    "진자",
  ][i % 9];
  highScience.push(
    question(
      `high1-science-q-${String(i + 1).padStart(2, "0")}`,
      `${setup}의 유효 질량이 ${mass}kg이고 일정한 가속도 ${acceleration}m/s²를 낼 때, 저항을 무시한 알짜힘과 운동 변화에 대한 설명은?`,
      `알짜힘 ${force}N이며 속도 변화율은 ${acceleration}m/s²이다`,
      [
        `알짜힘 ${additiveForce}N이며 속도는 일정하다`,
        `알짜힘 ${force + acceleration}N이며 질량이 변한다`,
        `알짜힘 ${mass / acceleration}N이며 가속도는 0이다`,
      ],
      `뉴턴의 제2법칙 F=ma로 알짜힘은 ${mass}×${acceleration}=${force}N이고, 속도 변화율은 가속도와 같다.`,
      (i % 3) + 1,
      i % 4,
    ),
  );
}
for (let i = 0; i < 27; i++) {
  const concentration = 0.1 + (i % 5) * 0.05;
  const volume = 100 + (i % 6) * 20;
  const moles = Number(((concentration * volume) / 1000).toFixed(3));
  const reaction = [
    "산-염기 중화",
    "침전 생성",
    "기체 발생",
    "산화 환원",
    "용해 평형",
    "완충 용액",
  ][i % 6];
  highScience.push(
    question(
      `high1-science-q-${String(i + 28).padStart(2, "0")}`,
      `${reaction} 실험에서 ${concentration.toFixed(2)}mol/L 용액 ${volume}mL를 사용했다. 용질의 양과 농도 변화에 대한 해석으로 옳은 것은?`,
      `용질은 ${moles}mol이고 물을 더하면 몰수는 보존되며 농도는 낮아진다`,
      [
        "용질은 부피를 따라 사라져 몰수가 0이 된다",
        "물을 더하면 몰수가 증가하고 농도도 증가한다",
        "몰농도는 용액의 색만으로 결정된다",
      ],
      `몰수 n=CV이므로 ${concentration}×${volume / 1000}=${moles}mol이다. 희석 시 몰수는 보존되고 총부피가 증가해 농도가 낮아진다.`,
      (i % 3) + 1,
      i % 4,
    ),
  );
}
for (let i = 0; i < 26; i++) {
  const genotype =
    i % 3 === 0 ? "Aa × Aa" : i % 3 === 1 ? "Aa × aa" : "AA × aa";
  const dominant = i % 3 === 0 ? "75%" : i % 3 === 2 ? "100%" : "50%";
  const phenotype = [
    "씨 색",
    "효소 활성",
    "꽃 높이",
    "면역 표지",
    "잎 모양",
    "대사 속도",
  ][i % 6];
  const environment = [
    "온실",
    "습지",
    "산지",
    "해안",
    "도시 화단",
    "실험 배양기",
  ][i % 6];
  const generation = 2 + (i % 5);
  highScience.push(
    question(
      `high1-science-q-${String(i + 55).padStart(2, "0")}`,
      `${environment} ${generation}세대의 ${phenotype}에서 A가 완전 우성이고 부모 유전자형이 ${genotype}이다. 독립 분리와 무작위 수정을 가정할 때 우성 표현형의 예상 비율은? (표본 ${i + 1})`,
      dominant,
      [
        i % 3 === 0 ? "25%" : i % 3 === 2 ? "75%" : "100%",
        i % 3 === 2 ? "50%" : "0%",
        "유전자형에 관계없이 33%",
      ],
      `Punnett 표를 작성하면 ${genotype}에서 A를 하나 이상 갖는 자손의 비율이 ${dominant}가 된다.`,
      (i % 3) + 1,
      i % 4,
    ),
  );
}

